/*
 * Genesis Render - JSON scene loader
 *
 * Scenes shipped inside an asset package are plain JSON documents that map
 * one-to-one onto the engine's ECS components and the reflected material /
 * render setting objects.  Keeping the format declarative means it can be
 * authored by hand, generated by DCC tools or produced by the offline packer,
 * and it exercises exactly the same C++ paths as the editor.
 *
 * See docs/ASSET_PACKAGES.md for the complete schema.
 */
#ifndef __GENESIS_SCENE_LOADER_HPP__
#define __GENESIS_SCENE_LOADER_HPP__

#include <string>

namespace Genesis
{
    class Engine;

    namespace Scene
    {
        struct LoadResult
        {
            bool ok = false;
            size_t entities = 0;
            size_t materials = 0;
            size_t scripts = 0;
            size_t physics_bodies = 0;
            std::string error;
        };

        // `asset_root` is prepended to every relative path (textures, models,
        // shaders, scripts).  The loader adds entities to the current world;
        // callers that want a clean scene should reset it first.
        LoadResult loadFromFile(Engine &engine, const std::string &scene_path, const std::string &asset_root);
        LoadResult loadFromText(Engine &engine, const std::string &json, const std::string &asset_root,
                                const std::string &debug_name = "scene");

    } // namespace Scene
} // namespace Genesis

#endif /* __GENESIS_SCENE_LOADER_HPP__ */
